const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const blocos = linhas.map(
  (p, i) => `${i + 1}. ${p.nome_produto} (cód. ${p.codigo_produto}) — ${Math.round(Number(p.quantidade_vendida_30d))} ${Math.round(Number(p.quantidade_vendida_30d)) === 1 ? 'vendido' : 'vendidos'} em 30d`
);

const mensagem = `📦 *Estoque zerado — produtos de giro alto*\n📅 ${hojeLabel}\n\n${blocos.join('\n')}\n\nRepor com prioridade — são os produtos que mais vendem e estão zerados agora.`;

return [{ json: { mensagem } }];
